import React from 'react';
import { Link } from 'react-router-dom';

const Dashboard: React.FC = () => {
    return (
        <div style={{ padding: 20 }}>
            <h1>Mental Health Dashboard</h1>
            <p>Welcome to your mental health metrics and insights.</p>
            <div style={{ marginTop: 16 }}>
                <Link to="/rppg"><button>Open RPPG Camera & Analysis</button></Link>
            </div>
            <div style={{ marginTop: 12 }}>
                <Link to="/patient/1"><button>View Sample Patient Profile</button></Link>
            </div>
        </div>
    );
};

export default Dashboard;
